# Run from the repo root, after johto_route_trainers.py.
# Trainer class pools + Johto route trainers on pooled teams.
#  - Adds pools for 22 trainer classes to src/data/trainer_pools.h (same naming as the Hiker pools):
#      _Advanced      Johto (postgame): fully evolved, 4 moves, held item, ability (generated sets)
#      _Basic         Orange Islands, early: species only
#      _Intermediate  Orange Islands, later: species only, IV 100
#  - Johto route trainers now roll their team from their class's _Advanced pool (hikers use the
#    existing sPool_Hiker_Advanced): team size from their HG/SS team (at least 2), level = the
#    route's band. The roll is fixed per save (see include/trainer_pools.h).
#  - The fixed Johto parties (sParty_Johto*) are removed.
import re

def rd(p): return open(p, encoding='utf-8').read()
def wr(p, s): open(p, 'w', newline='\n', encoding='utf-8').write(s)

